# ── Skill Runner (same logic as learn.py) ──
def run_skill(name: str, args: list[str], timeout: int = 60) -> dict:
    """Run a skill via its run.sh and capture output."""
    candidates = [
        SKILLS_DIR / name / "run.sh",
        AGENT_SKILLS_DIR / name / "run.sh",
    ]
    script = None
    for c in candidates:
        if c.exists():
            script = c
            break
    if not script:
        return {"returncode": -1, "stdout": "", "stderr": f"Skill {name} not found", "skipped": True}

    try:
        result = subprocess.run(
            [str(script)] + args,
            capture_output=True,
            text=True,
            timeout=timeout,
            cwd=str(script.parent),
        )
        return {
            "returncode": result.returncode,
            "stdout": result.stdout,
            "stderr": result.stderr,
            "skipped": False,
        }
    except subprocess.TimeoutExpired:
        return {"returncode": -2, "stdout": "", "stderr": f"Timed out ({timeout}s)", "skipped": False}
    except Exception as e:
        return {"returncode": -3, "stdout": "", "stderr": str(e), "skipped": False}


def parse_json_output(stdout: str):
    """Parse JSON from skill output."""
    stdout = stdout.strip()
    if not stdout:
        return None
    try:
        return json.loads(stdout)
    except json.JSONDecodeError:
        pass
    idx = stdout.find("{")
    if idx >= 0:
        try:
            return json.loads(stdout[idx:])
        except json.JSONDecodeError:
            pass
    return None


