# Fix 1: doc2qra distill JSON output
# ═══════════════════════════════════════════════════════════════════════════
def test_fix1_doc2qra_distill() -> bool:
    """Verify QRA extraction via chutes-call /batch HTTP service (port 8630)."""
    banner("Fix 1: QRA extraction via chutes-call /batch")
    passed = True

    test_text = (
        "# Chronic Stress and the Hippocampus\n\n"
        "Chronic stress causes elevated cortisol levels which damage the hippocampus, "
        "impairing memory formation and spatial reasoning. Robert Sapolsky's research "
        "at Stanford demonstrated that baboons with lower social rank experienced "
        "sustained glucocorticoid exposure, leading to hippocampal atrophy.\n\n"
        "## Amygdala Hyperactivity\n\n"
        "The amygdala, conversely, becomes hyperactive under chronic stress, "
        "increasing anxiety and fear responses. This creates a feedback loop: "
        "stress damages the brain regions needed to regulate stress.\n\n"
        "## Interventions\n\n"
        "Interventions include mindfulness meditation, which reduces cortisol "
        "by 23% in controlled studies, and social support networks, which "
        "buffer the HPA axis response. Exercise promotes BDNF release, "
        "which helps repair hippocampal neurons damaged by glucocorticoids."
    )

    _CHUTES_CALL_URL = os.environ.get("CHUTES_CALL_URL", "http://localhost:8630")

    # ── Test 1a: chutes-call /batch health check ──
    info_msg("Test 1a: Checking chutes-call /batch health...")
    try:
        health_resp = urllib.request.urlopen(f"{_CHUTES_CALL_URL}/health", timeout=5)
        health_data = json.loads(health_resp.read())
        if health_data.get("ok") or health_data.get("status") == "ok":
            pass_msg(f"chutes-call service healthy at {_CHUTES_CALL_URL}")
        else:
            fail_msg(f"chutes-call unhealthy: {health_data}")
            return False
    except Exception as e:
        fail_msg(f"chutes-call unreachable at {_CHUTES_CALL_URL}: {e}")
        return False

    # ── Test 1b: Send QRA extraction request to chutes-call /batch ──
    info_msg("Test 1b: Sending QRA extraction to chutes-call /batch...")
    t0 = time.time()

    payload = json.dumps({
        "requests": [{
            "messages": [
                {"role": "system", "content": (
                    "You are a knowledge extraction assistant. Respond with valid JSON only. "
                    'Return {"items": [{"question": "string", "reasoning": "string", "answer": "string"}, ...]}'
                )},
                {"role": "user", "content": f"Extract all grounded knowledge items from this text.\n\nText:\n{test_text}\n\nJSON:"},
            ],
            "response_format": {"type": "json_object"},
            "max_tokens": 4096,
            "temperature": 0.1,
        }],
        "concurrency": 1,
        "tenacious": True,
        "caller": "test-e2e-fixes",
    }).encode("utf-8")

    try:
        req = urllib.request.Request(
            f"{_CHUTES_CALL_URL}/batch",
            data=payload,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=120) as resp:
            body = json.loads(resp.read().decode("utf-8"))
    except Exception as e:
        fail_msg(f"chutes-call /batch request failed: {e}")
        return False

    elapsed = time.time() - t0
    info_msg(f"  Completed in {elapsed:.1f}s")

    if not isinstance(body, list) or not body:
        fail_msg(f"Expected list response, got {type(body).__name__}")
        return False

    result = body[0]
    if not result.get("ok"):
        fail_msg(f"chutes-call returned error: {result.get('error', 'unknown')}")
        return False

    pass_msg("chutes-call /batch returned ok=True")

    # Parse the LLM content for QRA items
    content_str = result.get("content", "")
    try:
        parsed = json.loads(content_str) if isinstance(content_str, str) else content_str
    except (json.JSONDecodeError, TypeError):
        parsed = None

    if parsed is None or not isinstance(parsed, dict):
        fail_msg("LLM response is NOT parseable JSON")
        info_msg(f"  Raw content: {str(content_str)[:200]}...")
        passed = False
    else:
        pass_msg("LLM returned valid JSON")
        info_msg(f"  Keys: {list(parsed.keys())}")

        items = parsed.get("items", [])
        if items:
            pass_msg(f"Extracted {len(items)} QRA items from test text")
            for qa in items[:2]:
                info_msg(f"  Q: {qa.get('question', '')[:60]}")
        else:
            warn_msg("No QRA items extracted (LLM returned empty items)")

    return passed


