# Fix 2: ingest-youtube stdout parsing regardless of return code
# ═══════════════════════════════════════════════════════════════════════════
def test_fix2_youtube_stdout_parsing() -> bool:
    """Verify ingest-youtube stdout JSON is parsed even on exit code 1."""
    banner("Fix 2: ingest-youtube stdout parsing")
    passed = True

    # Use a known short video. This may fail (API issues) which is what we want to test.
    # The key assertion: stdout JSON is parseable regardless of return code.
    test_url = "https://www.youtube.com/watch?v=dQw4w9WgXcQ"  # Rick Astley — short, widely available

    info_msg(f"Calling ingest-youtube with: {test_url}")
    info_msg("(Expected: JSON output on stdout regardless of success/failure)")
    t0 = time.time()
    result = run_skill("ingest-youtube", [test_url], timeout=120)
    elapsed = time.time() - t0

    returncode = result["returncode"]
    stdout = result["stdout"].strip()
    stderr = result["stderr"].strip()

    info_msg(f"Completed in {elapsed:.1f}s")
    info_msg(f"Return code: {returncode}")
    info_msg(f"Stdout length: {len(stdout)} bytes")
    info_msg(f"Stderr length: {len(stderr)} bytes")

    if returncode == -2:
        fail_msg("ingest-youtube timed out (120s)")
        return False

    if result.get("skipped"):
        fail_msg("ingest-youtube skill not found")
        return False

    # ── Core assertion: stdout is parseable JSON regardless of return code ──
    parsed = parse_json_output(stdout)

    if parsed is None:
        if stdout:
            fail_msg(f"Stdout is not parseable JSON (code={returncode})")
            info_msg(f"  First 200 chars: {stdout[:200]}")
        else:
            fail_msg(f"Stdout is empty (code={returncode})")
            info_msg(f"  Stderr: {stderr[:200]}")
        passed = False
    elif not isinstance(parsed, dict):
        fail_msg(f"Parsed output is {type(parsed).__name__}, expected dict")
        passed = False
    else:
        pass_msg(f"Stdout is valid JSON (return code={returncode})")
        info_msg(f"  Keys: {list(parsed.keys())}")

        # Check expected schema fields
        has_meta = "meta" in parsed
        has_full_text = "full_text" in parsed
        has_errors = "errors" in parsed
        has_transcript = "transcript" in parsed

        if has_meta:
            pass_msg("JSON has 'meta' field")
            info_msg(f"  meta: {json.dumps(parsed['meta'])[:100]}")
        else:
            warn_msg("JSON missing 'meta' field")

        if has_full_text:
            full_text = parsed["full_text"]
            if full_text:
                pass_msg(f"JSON has 'full_text' with {len(full_text)} chars")
            else:
                info_msg("JSON has 'full_text' but it's empty (expected on failure)")
        else:
            warn_msg("JSON missing 'full_text' field")

        if has_errors:
            errors = parsed["errors"]
            if errors:
                pass_msg(f"JSON has 'errors' array with {len(errors)} entries (structured error capture)")
                for err in errors[:3]:
                    info_msg(f"  Error: {str(err)[:100]}")
            else:
                pass_msg("JSON has 'errors' array (empty — success case)")
        else:
            warn_msg("JSON missing 'errors' field")

        if has_transcript:
            pass_msg(f"JSON has 'transcript' array ({len(parsed['transcript'])} segments)")

    # ── Verify learn.py would handle this correctly ──
    info_msg("")
    info_msg("Simulating learn.py's new handling logic:")
    if parsed and isinstance(parsed, dict):
        full_text = parsed.get("full_text", "")
        yt_errors = parsed.get("errors", [])

        if yt_errors:
            for yt_err in yt_errors[:3]:
                info_msg(f"  Would log error: {str(yt_err)[:100]}")

        if full_text:
            status = "partial" if returncode != 0 else "full"
            pass_msg(f"learn.py would capture transcript ({len(full_text)} chars, {status})")
        else:
            err_summary = yt_errors[0] if yt_errors else "no transcript text"
            info_msg(f"learn.py would log: No transcript: {str(err_summary)[:60]}")
            if returncode != 0:
                pass_msg("learn.py correctly captures error details instead of just 'Failed: unknown'")
    else:
        fail_msg("learn.py would fall through to 'Failed: unknown error' (old behavior)")
        passed = False

    return passed


