# Fix 3: MEMORY_SERVICE_TIMEOUT=180
# ═══════════════════════════════════════════════════════════════════════════
def test_fix3_memory_timeout() -> bool:
    """Verify memory learn call succeeds with extended timeout."""
    banner("Fix 3: MEMORY_SERVICE_TIMEOUT=180")
    passed = True

    test_problem = f"E2E test: What is the effect of chronic stress on the hippocampus?"
    test_solution = (
        f"E2E test ({TEST_SCOPE}): Chronic stress elevates cortisol, causing hippocampal "
        f"atrophy and impaired memory. Sapolsky demonstrated this in baboon studies."
    )

    # ── Test 3a: Verify env var propagation ──
    info_msg("Test 3a: Verifying MEMORY_SERVICE_TIMEOUT env var propagation...")

    # Save and set
    prev = os.environ.get("MEMORY_SERVICE_TIMEOUT")
    os.environ["MEMORY_SERVICE_TIMEOUT"] = "180"

    # Verify it's set
    current = os.environ.get("MEMORY_SERVICE_TIMEOUT")
    if current == "180":
        pass_msg("MEMORY_SERVICE_TIMEOUT set to 180")
    else:
        fail_msg(f"MEMORY_SERVICE_TIMEOUT is '{current}', expected '180'")
        passed = False

    # ── Test 3b: Call memory learn with extended timeout ──
    info_msg("Test 3b: Calling memory learn with timeout=180 (exercises taxonomy tagging)...")
    t0 = time.time()
    try:
        result = run_skill("memory", [
            "learn",
            "--problem", test_problem,
            "--solution", test_solution,
            "--scope", TEST_SCOPE,
        ], timeout=180)
    finally:
        # Restore env var
        if prev is not None:
            os.environ["MEMORY_SERVICE_TIMEOUT"] = prev
        else:
            os.environ.pop("MEMORY_SERVICE_TIMEOUT", None)
    elapsed = time.time() - t0

    info_msg(f"Completed in {elapsed:.1f}s, return code: {result['returncode']}")

    if result["returncode"] == 0:
        pass_msg(f"Memory learn succeeded in {elapsed:.1f}s")

        # Parse response
        parsed = parse_json_output(result["stdout"].strip())
        if parsed and isinstance(parsed, dict):
            meta = parsed.get("meta", {})
            embedding = meta.get("embedding_created", False)
            info_msg(f"  embedding_created: {embedding}")
            info_msg(f"  meta keys: {list(meta.keys())}")

            if embedding:
                pass_msg("Embedding was created (full pipeline including taxonomy)")
            else:
                warn_msg("Embedding NOT created (may need embedding service)")

            if elapsed > 30:
                pass_msg(f"Took {elapsed:.1f}s > 30s — old 30s timeout would have failed")
            else:
                info_msg(f"Completed in {elapsed:.1f}s (< 30s — fast, but timeout fix still needed for slow cases)")
        else:
            info_msg(f"  Raw stdout: {result['stdout'][:200]}")
    elif result["returncode"] == -2:
        fail_msg(f"Memory learn timed out even with 180s timeout ({elapsed:.1f}s)")
        passed = False
    else:
        # CLI failed — try the API fallback (same as learn.py does)
        warn_msg(f"Memory CLI failed (code={result['returncode']}), testing API fallback...")
        info_msg(f"  stderr: {result['stderr'][:150]}")

        try:
            payload = json.dumps({
                "problem": test_problem,
                "solution": test_solution,
                "scope": TEST_SCOPE,
            }).encode("utf-8")

            req = urllib.request.Request(
                f"{MEMORY_API_URL}/learn",
                data=payload,
                headers={"Content-Type": "application/json"},
                method="POST",
            )
            t0_api = time.time()
            with urllib.request.urlopen(req, timeout=180) as resp:
                body = json.loads(resp.read().decode("utf-8"))
                api_elapsed = time.time() - t0_api
                ok = body.get("meta", {}).get("ok", False)
                if ok:
                    pass_msg(f"API fallback succeeded in {api_elapsed:.1f}s")
                else:
                    warn_msg(f"API fallback returned ok=False: {json.dumps(body)[:150]}")
        except Exception as e:
            fail_msg(f"API fallback also failed: {e}")
            passed = False

    # ── Test 3c: Verify env var was restored ──
    info_msg("Test 3c: Verifying env var cleanup...")
    current_after = os.environ.get("MEMORY_SERVICE_TIMEOUT")
    if current_after == prev:
        pass_msg(f"MEMORY_SERVICE_TIMEOUT restored to {'(unset)' if prev is None else prev}")
    else:
        fail_msg(f"MEMORY_SERVICE_TIMEOUT is '{current_after}', expected '{prev}'")
        passed = False

    # ── Test 3d: Verify the stored item can be recalled ──
    info_msg("Test 3d: Verifying stored item can be recalled...")
    time.sleep(2)  # Brief delay for indexing
    recall_result = run_skill("memory", [
        "recall",
        "--q", "chronic stress hippocampus cortisol",
        "--scope", TEST_SCOPE,
        "--k", "3",
    ], timeout=30)

    if recall_result["returncode"] == 0:
        recall_parsed = parse_json_output(recall_result["stdout"].strip())
        if recall_parsed and isinstance(recall_parsed, dict):
            items = recall_parsed.get("items", [])
            if items:
                pass_msg(f"Recall found {len(items)} items in scope '{TEST_SCOPE}'")
                for item in items[:2]:
                    info_msg(f"  - {item.get('problem', '')[:60]}")
            else:
                warn_msg("Recall returned 0 items (may need more indexing time)")
        else:
            warn_msg(f"Could not parse recall output")
    else:
        warn_msg(f"Recall failed (code={recall_result['returncode']})")

    return passed


