    """Run the complete learn pipeline end-to-end with a real topic."""
    banner("Full Pipeline: learn → ask round-trip")
    passed = True

    # Use a focused topic that's likely to produce results
    test_topic = "cortisol stress response hippocampus"
    full_scope = f"test-full-{int(time.time())}"

    info_msg(f"Topic: {test_topic}")
    info_msg(f"Scope: {full_scope}")
    info_msg(f"This will run the full dogpile → ingest → extractor → memory pipeline")
    info_msg(f"Expected duration: 5-15 minutes")
    print()

    # Run learn.py directly
    t0 = time.time()
    env = os.environ.copy()
    env["ASK_DEBUG"] = "1"
    env["MEMORY_SERVICE_TIMEOUT"] = "180"

    try:
        result = subprocess.run(
            [sys.executable, str(SCRIPT_DIR / "learn.py"),
             test_topic,
             "--scope", full_scope,
             "--max-videos", "1",
             "--max-books", "2",
             "--debug",
             ],
            capture_output=True,
            text=True,
            timeout=900,  # 15 min max
            cwd=str(SCRIPT_DIR),
            env=env,
        )
    except subprocess.TimeoutExpired:
        fail_msg("Full pipeline timed out after 15 minutes")
        return False

    elapsed = time.time() - t0
    info_msg(f"Pipeline completed in {elapsed:.1f}s, return code: {result.returncode}")

    # Print stderr (debug logs) to a file for inspection
    log_file = SCRIPT_DIR / "test_e2e_pipeline.log"
